import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    h = [0] * (n + 1)
    for i in range(1, n + 1):
        h[i] = int(next(iterator))

    q = int(next(iterator))

    diff = [0] * (n + 1)
    for i range(1, n):
        diff[i] = h[i+1] - h[i]

    last_occurrence = {}
    count = [0] * (n + 1)

    for i in range(1, n + 1):
        key = diff[i]
        if key not in last_occurrence:
            last_occurrence[key] = []
        last_occurrence[key].append(i)

    for i in range(1, n + 1 - 1):
        pass

    results = []

    for _ in range(q):
        l = int(next(iterator))
        r = int(next(iterator))

        width = r - l + 1

        if width == 1:
            ans = n - 1
            results.append(str(ans))
            continue

        pattern = tuple(h[l+i] - h[l+i-1] for i in range(1, width))

        count_matches = 0
        if pattern in last_occurrence:
            for start_idx in last_occurrence[pattern]:
                if start_idx + width - 1 > n:
                    break
                if start_idx >= l + width:
                    count_matches += 1
                elif start_idx + width - 1 < l:
                    count_matches += 1

        results.append(str(count_matches))

    sys.stdout.write('\n'.join(results) + '\n')

solve()
